//go:build loong64

package gf65536

// LSX kernels (vshuf.b split tables) generated by go-asmgen
// (gen/galois_loong64_gen.go) into galois_loong64.s. They use only 128-bit LSX
// baseline operations, so there is no feature check.
func galMulLSX(dst, src []byte, tbl *[128]byte, n int)
func galMulAddLSX(dst, src []byte, tbl *[128]byte, n int)

func archTiers() []tier {
	return []tier{blockTier("lsx", galMulLSX, galMulAddLSX)}
}
